import java.util.*;
import java.io.*;

public class Main {
    static final long mod = 1000000007;
    static long[] parent;
    static long[] rating;

    static long findParent(long root) {
        while (parent[(int) root] != root) {
            root = parent[(int) root];
        }
        return root;
    }

    static void findUnion(long root1, long root2) {
        long par1 = findParent(root1);
        long par2 = findParent(root2);
        if (rating[(int) par1] >= rating[(int) par2]) {
            parent[(int) par2] = par1;
            rating[(int) par1]++;
        } else {
            parent[(int) par1] = par2;
            rating[(int) par2]++;
        }
    }

    static void init(int n) {
        parent = new long[n + 1];
        rating = new long[n + 1];
        for (int i = 0; i <= n; i++) {
            parent[i] = i;
            rating[i] = 0;
        }
    }

    static long modularExponentiation(long x, long n, long M) {
        if (n == 0)
            return 1;
        else if (n % 2 == 0)
            return modularExponentiation((x * x) % M, n / 2, M);
        else
            return (x * modularExponentiation((x * x) % M, (n - 1) / 2, M)) % M;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        init(n);

        if (m == 0) {
            System.out.println(modularExponentiation(n, n - 1, mod));
        } else if (m == 1) {
            System.out.println(modularExponentiation(n, n, mod));
        } else {
            for (int i = 1; i < n; i++) {
                long bash = (i * m) % n;
                findUnion(i, bash);
            }
            Set<Long> s = new HashSet<>();
            for (int i = 1; i < n; i++) {
                parent[i] = findParent(i);
                s.add(parent[i]);
            }
            long sz = s.size();
            System.out.println(modularExponentiation(n, sz, mod));
        }
    }
}
